int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int M = N * (N - 1) / 2;

    int *A = (int *)malloc((size_t)N * (N - 1) * sizeof(int));
    int *pos = (int *)malloc((size_t)N * N * sizeof(int));
    if (!A || !pos) return 0;

    for (int i = 0; i < N * N; i++) pos[i] = -1;

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N - 1; j++) {
            int x;
            scanf("%d", &x);
            x--;
            A[i * (N - 1) + j] = x;
            pos[i * N + x] = j;
        }
    }

    int *head = (int *)malloc((size_t)M * sizeof(int));
    int *indeg = (int *)calloc((size_t)M, sizeof(int));
    int *dp = (int *)malloc((size_t)M * sizeof(int));
    Edge *edges = (Edge *)malloc((size_t)(N * (N - 2)) * sizeof(Edge));
    int *queue = (int *)malloc((size_t)M * sizeof(int));
    if (!head || !indeg || !dp || !edges || !queue) return 0;

    for (int i = 0; i < M; i++) head[i] = -1;

    int edge_cnt = 0;

    // Map each unordered pair (i, j), i < j, to a unique match id
    int *id = (int *)malloc((size_t)N * N * sizeof(int));
    if (!id) return 0;
    for (int i = 0; i < N * N; i++) id[i] = -1;

    int cur = 0;
    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            id[i * N + j] = id[j * N + i] = cur++;
        }
    }

    // For each player, consecutive matches in their list create directed edges
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N - 2; j++) {
            int a = A[i * (N - 1) + j];
            int b = A[i * (N - 1) + j + 1];
            int u = id[i * N + a];
            int v = id[i * N + b];

            edges[edge_cnt].to = v;
            edges[edge_cnt].next = head[u];
            head[u] = edge_cnt++;
            indeg[v]++;
        }
    }

    // Topological sort + longest path in DAG
    int qh = 0, qt = 0;
    for (int i = 0; i < M; i++) {
        dp[i] = 1;
        if (indeg[i] == 0) queue[qt++] = i;
    }

    int visited = 0;
    int ans = 0;

    while (qh < qt) {
        int u = queue[qh++];
        visited++;
        if (dp[u] > ans) ans = dp[u];

        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (dp[v] < dp[u] + 1) dp[v] = dp[u] + 1;
            indeg[v]--;
            if (indeg[v] == 0) queue[qt++] = v;
        }
    }

    if (visited != M) {
        printf("-1\n");
    } else {
        printf("%d\n", ans);
    }

    free(A);
    free(pos);
    free(head);
    free(indeg);
    free(dp);
    free(edges);
    free(queue);
    free(id);

    return 0;
}

