int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<int>> A(N, vector<int>(N - 1));
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N - 1; ++j) {
            cin >> A[i][j];
            --A[i][j];
        }
    }

    vector<int> ptr(N, 0);
    queue<pair<int,int>> q;

    auto normalize = [](int x, int y) {
        if (x > y) swap(x, y);
        return make_pair(x, y);
    };

    for (int i = 0; i < N; ++i) {
        int j = A[i][0];
        if (A[j][0] == i) {
            q.push(normalize(i, j));
        }
    }

    int played = 0;
    int days = 0;

    while (!q.empty()) {
        int sz = (int)q.size();
        set<pair<int,int>> today;
        for (int k = 0; k < sz; ++k) {
            auto p = q.front();
            q.pop();
            today.insert(p);
        }

        ++days;
        vector<int> updated;

        for (auto [x, y] : today) {
            ++played;
            ++ptr[x];
            ++ptr[y];
            updated.push_back(x);
            updated.push_back(y);
        }

        for (int x : updated) {
            if (ptr[x] >= N - 1) continue;
            int y = A[x][ptr[x]];
            if (ptr[y] >= N - 1) continue;
            if (A[y][ptr[y]] == x) {
                q.push(normalize(x, y));
            }
        }
    }

    if (played == N * (N - 1) / 2) cout << days << '\n';
    else cout << -1 << '\n';

    return 0;
}

