public class TennisTournament {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        sc.nextLine();

        List<Queue<Integer>> opponents = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().split(" ");
            Queue<Integer> q = new LinkedList<>();
            for (String s : parts) {
                q.add(Integer.parseInt(s) - 1); // zero-index
            }
            opponents.add(q);
        }

        int totalMatches = n * (n - 1) / 2;
        int scheduled = 0;
        int days = 0;

        boolean[] playedToday = new boolean[n];
        boolean[] done = new boolean[n]; // player finished all matches

        while (scheduled < totalMatches) {
            Arrays.fill(playedToday, false);
            boolean progress = false;

            for (int i = 0; i < n; i++) {
                if (done[i] || playedToday[i] || opponents.get(i).isEmpty()) continue;
                int j = opponents.get(i).peek();
                if (done[j] || playedToday[j]) continue;
                if (!opponents.get(j).isEmpty() && opponents.get(j).peek() == i) {
                    // schedule match i vs j
                    opponents.get(i).poll();
                    opponents.get(j).poll();
                    playedToday[i] = true;
                    playedToday[j] = true;
                    scheduled++;
                    progress = true;
                    if (opponents.get(i).isEmpty()) done[i] = true;
                    if (opponents.get(j).isEmpty()) done[j] = true;
                }
            }

            if (!progress) {
                System.out.println(-1);
                return;
            }
            days++;
        }

        System.out.println(days);
    }
}

