public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();

        int[][] a = new int[N][N - 1];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N - 1; j++) {
                a[i][j] = fs.nextInt() - 1;
            }
        }

        int[] idx = new int[N];
        int[] day = new int[N];
        ArrayDeque<Integer> q = new ArrayDeque<>();

        for (int i = 0; i < N; i++) q.add(i);

        int completed = 0;
        int total = N * (N - 1) / 2;

        while (true) {
            boolean[] used = new boolean[N];
            ArrayList<int[]> today = new ArrayList<>();

            int qs = q.size();
            boolean[] inQueueNext = new boolean[N];

            for (int t = 0; t < qs; t++) {
                int i = q.poll();
                if (idx[i] >= N - 1 || used[i]) continue;

                int j = a[i][idx[i]];
                if (idx[j] >= N - 1 || used[j]) continue;

                if (a[j][idx[j]] == i) {
                    used[i] = used[j] = true;
                    today.add(new int[]{i, j});
                }
            }

            if (today.isEmpty()) break;

            for (int[] match : today) {
                int i = match[0], j = match[1];
                idx[i]++;
                idx[j]++;
                completed++;

                if (idx[i] < N - 1 && !inQueueNext[i]) {
                    q.add(i);
                    inQueueNext[i] = true;
                }
                if (idx[j] < N - 1 && !inQueueNext[j]) {
                    q.add(j);
                    inQueueNext[j] = true;
                }

                if (idx[i] < N - 1) {
                    int ni = a[i][idx[i]];
                    if (!inQueueNext[ni]) {
                        q.add(ni);
                        inQueueNext[ni] = true;
                    }
                }
                if (idx[j] < N - 1) {
                    int nj = a[j][idx[j]];
                    if (!inQueueNext[nj]) {
                        q.add(nj);
                        inQueueNext[nj] = true;
                    }
                }

                day[i]++;
                day[j]++;
            }
        }

        if (completed != total) {
            System.out.println(-1);
            return;
        }

        // Correct minimum days via DAG longest path on matches
        int M = total;
        int[][] matchId = new int[N][N];
        for (int i = 0; i < N; i++) Arrays.fill(matchId[i], -1);

        int id = 0;
        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                matchId[i][j] = matchId[j][i] = id++;
            }
        }

        ArrayList<Integer>[] g = new ArrayList[M];
        int[] indeg = new int[M];
        for (int i = 0; i < M; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < N; i++) {
            for (int k = 0; k < N - 2; k++) {
                int u = matchId[i][a[i][k]];
                int v = matchId[i][a[i][k + 1]];
                g[u].add(v);
                indeg[v]++;
            }
        }

        ArrayDeque<Integer> topo = new ArrayDeque<>();
        int[] dist = new int[M];
        Arrays.fill(dist, 1);

        for (int i = 0; i < M; i++) {
            if (indeg[i] == 0) topo.add(i);
        }

        int seen = 0;
        int ans = 1;
        while (!topo.isEmpty()) {
            int u = topo.poll();
            seen++;
            ans = Math.max(ans, dist[u]);
            for (int v : g[u]) {
                if (dist[v] < dist[u] + 1) dist[v] = dist[u] + 1;
                if (--indeg[v] == 0) topo.add(v);
            }
        }

        if (seen != M) {
            System.out.println(-1);
        } else {
            System.out.println(ans);
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

