from collections import deque

def main():
    input = sys.stdin.readline
    N = int(input())
    A = []
    for _ in range(N):
        row = list(map(int, input().split()))
        A.append([x - 1 for x in row])

    # Give each unordered pair (i, j) a unique id
    match_id = {}
    idx = 0
    for i in range(N):
        for j in range(i + 1, N):
            match_id[(i, j)] = idx
            idx += 1

    M = idx  # total number of matches

    def get_id(i, j):
        if i > j:
            i, j = j, i
        return match_id[(i, j)]

    # Build DAG:
    # For each player, consecutive matches in their required order
    # create directed edges.
    graph = [[] for _ in range(M)]
    indeg = [0] * M

    for i in range(N):
        seq = A[i]
        for k in range(N - 2):
            u = get_id(i, seq[k])
            v = get_id(i, seq[k + 1])
            graph[u].append(v)
            indeg[v] += 1

    # Topological sort + longest path in DAG
    q = deque()
    dp = [1] * M  # earliest day for each match

    for v in range(M):
        if indeg[v] == 0:
            q.append(v)

    visited = 0
    while q:
        u = q.popleft()
        visited += 1
        for v in graph[u]:
            if dp[v] < dp[u] + 1:
                dp[v] = dp[u] + 1
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)

    if visited != M:
        print(-1)
    else:
        print(max(dp))

